ruleSearch.bookUrl:
class.item-text@tag.a.0@href<js>
if(result.match(/\/art/)!=null)
result;
else{
result='https://m.zydu1.com'+result;
h=String(java.ajax(result));
url=h.match(/location.href="(.*?)";/);
if(url!=null)
result=url[1];
else
